package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.config.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.settings.SettingsUpdateService;
import java.util.List;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.PlatformTransactionManager;

/** Actual configuration, original partial source data, owned databases and zero model calls. */
class SourcePartialRuntimeProofConfigurationTest {
    SourcePartialPlanCoordinatorTest q;SettingsUpdateService settings;OperationalInputGate gate;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(int count,boolean mixed)throws Exception{q=new SourcePartialPlanCoordinatorTest(){@Override GenerationJdbcStoreTest database(){return SourcePartialRuntimeProofConfigurationTest.this.database();}};q.setup(count,mixed);q.db.jdbc.update("UPDATE jobs SET operator_id='analysis-worker' WHERE target_type='generation_prepare'");settings=mock(SettingsUpdateService.class);when(settings.freezeForNewInput()).thenReturn(new SettingsUpdateService.Frozen(7,List.of("Fictional watched"),List.of(),null));gate=mock(OperationalInputGate.class);when(gate.preparationAllowed()).thenReturn(true);}
    ApplicationContextRunner context(){return new ApplicationContextRunner().withUserConfiguration(NewsSourcePreparationConfiguration.class,ResultApplicationConfiguration.class,DispatchReadinessConfiguration.class).withBean(DataSource.class,()->q.db.source).withBean(PlatformTransactionManager.class,()->new DataSourceTransactionManager(q.db.source)).withBean(SettingsUpdateService.class,()->settings).withBean(OperationalInputGate.class,()->gate).withPropertyValues("site.browser.enabled=true","site.content.enabled=true","site.articles.enabled=true","site.sources.enabled=true","site.execution.enabled=true","site.collector.enabled=true","site.execution.preparation.enabled=true","site.execution.worker.enabled=false");}
    @Test void Actual201ConfiguredPartialPlanUsesTheSameWriterAuthorityForEveryOriginalPart()throws Exception{setup(201,true);context().run(c->{assertNull(c.getStartupFailure());var g=c.getBean(SourceAnalysisProofGraph.class);var coordinator=c.getBean(SourcePlanPreparationCoordinator.class);var prepared=coordinator.prepareValuePartial(q.intent,"fictional-run",q.q.h.ref,0);assertEquals(201,prepared.plan().decisions().size());assertEquals(200,prepared.plan().chunks().stream().mapToInt(p->p.itemIds().size()).sum());assertTrue(prepared.plan().chunks().size()>1);assertEquals(7,prepared.plan().scope().settings().revision());for(int n=1;n<prepared.plan().chunks().size();n++)assertEquals(prepared.plan(),coordinator.prepareValuePartial(q.intent,"fictional-run",q.q.h.ref,n).plan());var readiness=c.getBean(DispatchReadinessService.class);for(var part:prepared.plan().chunks()){assertEquals(Boolean.TRUE,q.q.h.f.readonly(()->readiness.preflight(part.rootId())));var captured=readiness.capturePartial(part.rootId());assertNotNull(captured);assertTrue(q.q.h.f.p1.tx(()->readiness.readyPartial(part.rootId(),captured)));assertThrows(RuntimeException.class,()->q.q.h.f.p1.tx(()->readiness.ready(part.rootId())));}assertSame(g.parts(),c.getBean(SourceStagePreparationService.class));String root=prepared.plan().chunks().getFirst().rootId();var captured=readiness.capturePartial(root);q.db.jdbc.update("UPDATE source_run_items SET revision=revision+1 WHERE id=?",prepared.plan().chunks().getFirst().itemIds().getFirst());assertEquals(Boolean.FALSE,q.q.h.f.readonly(()->readiness.preflight(root)));assertFalse(q.q.h.f.p1.tx(()->readiness.readyPartial(root,captured)));assertEquals(0,q.db.count("target_type='worker_claim' OR target_type='worker_send'"));verify(settings,times(2)).freezeForNewInput();});}
    @Test void ConfiguredFailedP1ZeroValueFinalizesAndCommittedPlanReplaysWithGateClosed()throws Exception{setup(1,false);context().run(c->{assertNull(c.getStartupFailure());var coordinator=c.getBean(SourcePlanPreparationCoordinator.class);var prepared=coordinator.prepareValuePartial(q.intent,"fictional-run",q.q.h.ref,0);assertNull(prepared.root());assertTrue(prepared.plan().chunks().isEmpty());var ref=q.q.h.f.readonly(()->FrozenSourceStagePlan.Reference.fromJson(JdbcFrozenInputs.canonical(CanonicalJson.parse(new JdbcFrozenSourcePlans(q.db.source).immutableReceipt(q.intent).payloadJson()).get("plan_ref"))));var g=c.getBean(SourceAnalysisProofGraph.class);g.valueSeals().seal(ref);assertNotNull(c.getBean(SourceValueFinalizationService.class).finish(ref));assertNotNull(c.getBean(SourceValueFinalAvailabilityService.class).capture(ref));assertEquals("partial",q.db.jdbc.queryForObject("SELECT analysis_state FROM source_runs",String.class));assertEquals(0,q.db.count("record_kind='logical_task' AND task_type='news_value'"));int rows=q.db.count("1=1");when(gate.preparationAllowed()).thenReturn(false);assertEquals(prepared,coordinator.prepareValuePartial(q.intent,"fictional-run",q.q.h.ref,0));assertEquals(rows,q.db.count("1=1"));verify(settings,times(2)).freezeForNewInput();});}
}
